   14: impl DirAction {
   15:     /// Determine which action to perform when trying to list a directory.
   16:     /// There are three possible actions, and they overlap somewhat: the
   17:     /// `--tree` flag is another form of recursion, so those two are allowed
   18:     /// to both be present, but the `--list-dirs` flag is used separately.
   19:     pub fn deduce(matches: &MatchedFlags<'_>, can_tree: bool) -> Result<Self, OptionsError> {
   20:         let recurse = matches.has(&flags::RECURSE)?;
   21:         let as_file =
   22:             matches.has(&flags::TREAT_DIRS_AS_FILES)? || matches.has(&flags::LIST_DIRS)?;
   23:         let tree = matches.has(&flags::TREE)?;
   24: 
   25:         if matches.is_strict() {
   26:             // Early check for --level when it wouldn’t do anything
   27:             if !recurse && !tree && matches.count(&flags::LEVEL) > 0 {
   28:                 return Err(OptionsError::Useless2(
   29:                     &flags::LEVEL,
   30:                     &flags::RECURSE,
   31:                     &flags::TREE,
   32:                 ));
   33:             } else if recurse && as_file {
   34:                 return Err(OptionsError::Conflict(
   35:                     &flags::RECURSE,
   36:                     &flags::TREAT_DIRS_AS_FILES,
   37:                 ));
   38:             } else if tree && as_file {
   39:                 return Err(OptionsError::Conflict(
   40:                     &flags::TREE,
   41:                     &flags::TREAT_DIRS_AS_FILES,
   42:                 ));
   43:             }
   44:         }
   45: 
   46:         if tree && can_tree {
   47:             // Tree is only appropriate in details mode, so this has to
   48:             // examine the View, which should have already been deduced by now
   49:             Ok(Self::Recurse(RecurseOptions::deduce(matches, true)?))
   50:         } else if recurse {
   51:             Ok(Self::Recurse(RecurseOptions::deduce(matches, false)?))
   52:         } else if as_file {
   53:             Ok(Self::AsFile)
   54:         } else {
   55:             Ok(Self::List)
   56:         }
   57:     }
   58: }
